    def _wait_until_test_model_operation_successful(self, start_time, timeout, operation_name, status_method_name,
                                                    delete_method_name, operation_id):
        get_method = getattr(self.local_client, status_method_name)
        delete_method = getattr(self.local_client, delete_method_name)
        polling_interval = 5

        stop_time = start_time + timeout
        status = get_method(operation_id=operation_id)["status"]

        while time.time() < stop_time:
            if status == 'success':
                delete_method(operation_id=operation_id)
                return status

            if status == 'failure':
                delete_method(operation_id=operation_id)
                raise WrongApiResponseStatus(f"{operation_name} failed")

            time.sleep(polling_interval)
            status = get_method(operation_id=operation_id)["status"]

        delete_method(operation_id=operation_id)
        raise WrongApiResponseStatus(f"{operation_name} didn't finish in given timeout. Status of the operation is {status}")

